 class eventclass_carrera_materia  extends eventsBase
{
	function __construct()
	{
	// fill list of events
		$this->events["BeforeAdd"]=true;


	}

//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$carrera_id = intval($values["carrera_id"]);
$materia_id = intval($values["materia_id"]);
$semestre   = intval($values["semestre"]);

if ($carrera_id <= 0 || $materia_id <= 0) {
    $message = "Debe seleccionar una carrera y una materia válidas.";
    return false;
}

if ($semestre < 1 || $semestre > 12) {
    $values["semestre"] = 1;
}

// Evitar duplicar materia en la misma carrera
$rsDup = DB::Query("SELECT id FROM carrera_materia WHERE carrera_id = " . $carrera_id . " AND materia_id = " . $materia_id . " LIMIT 1");
if ($rsDup->fetchAssoc()) {
    $message = "Esta materia ya se encuentra registrada en la malla curricular de esta carrera.";
    return false;
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



